def transform_to_agencies(data, month_idx):
    agencies = []
    for d in data:
        status = "달성" if d["수혜금액"] > 0 else "미달성"
        agencies.append({
            "id": d["코드"],
            "name": d["대리점명"],
            "summary": {
                "extraAidStatus": d["수혜금액"] > 0,
                "commonAidDetails": { "target": d["무선목표"], "registerRate": int(d["공통지원금등록률"] * 100) },
                "wirelessRate": int(d["무선달성률"] * 100),
                "wirelessDetails": { "target": d["무선목표"], "current": d["무선실적"], "rate": int(d["무선달성률"] * 100) },
                "wiredRate": int(d["유선달성률"] * 100),
                "wiredDetails": { "target": d["유선목표"], "current": d["유선실적"], "rate": int(d["유선달성률"] * 100) },
                "retailArpuRate": int(d["소매ARPU달성률"] * 100),
                "retailDetails": { "target": d["소매ARPU목표"], "current": d["소매ARPU실적"], "rate": int(d["소매ARPU달성률"] * 100) },
                "usimMnpRate": int(d["유심달성률"] * 100),
                "mnpDetails": { "target": d["유심목표"], "current": d["유심실적가점"], "rate": int(d["유심달성률"] * 100) },
                "totalAmount": d["수혜금액"],
                "unitPrice": 12000,
                "benefitHighUpgrade": d["고가기변"],
                "benefitHighMnp": d["고가MNP"],
                "benefitGal26": d["유심중고"]
            },
            "targetStatus": {
                "goalScore": 90,
                "currentScore": d["무선달성률"] * 100,
                "bonusUsageRate": d["공통지원금등록률"] * 100,
                "aiSuggestion": f"{month_idx}월 실적 리포트입니다."
            },
            "strengths": [{"name": "무선 활성", "score": 25}],
            "stores": [{"id": f"S-{d['코드']}", "name": f"{d['대리점명']} 본점", "wirelessPoint": int(d["무선실적"]), "wirelessPaymentTable": d["최종지급테이블"], "finalPayment": d["수혜금액"], "progressRate": int(d["무선달성률"] * 100)}]
        })
    return agencies

months = {}
base_data = get_base_data()

for i in range(1, 5):
    monthly_data = []
    for d in base_data:
        new_d = d.copy()
        factor = 0.8 + (i * 0.05) 
        new_d["무선실적"] = round(d["무선실적"] * factor, 1)
        new_d["유선실적"] = round(d["유선실적"] * factor, 1)
        new_d["무선달성률"] = round(new_d["무선실적"] / d["무선목표"], 3)
        new_d["유선달성률"] = round(new_d["유선실적"] / d["유선목표"], 3)
        new_d["수혜금액"] = int(d["수혜금액"] * factor) if d["수혜금액"] > 0 else 0
        monthly_data.append(new_d)
    
    months[i] = {
        "global": {
            "baseDate": f"2026-0{i}-28" if i < 2 else f"2026-0{i}-30",
            "totalBusinessDays": 22, "currentBusinessDay": 22,
            "wirelessDays": 27, "wiredDays": 23.1,
            "elapsedDays": 27, "wirelessProgress": 1.0, "wiredProgress": 1.0,
            "prevMonth": { "achievedCount": 15+i, "totalAmount": 100000000 + (i * 10000000) }
        },
        "agencies": transform_to_agencies(monthly_data, i),
        "allAgencies": monthly_data
    }

content = "const dashboardData = {\n    months: " + json.dumps(months, ensure_ascii=False, indent=4) + "\n};\n\nif (typeof module !== 'undefined') module.exports = dashboardData;"
print(content)
